insert into public.products (id, name, slug, description, price, image_url, gallery_urls, category, stock, badge)
values
  ('dd132556-de18-54e0-b4fe-060152fcddba', 'Agege Loaf', 'agege-loaf', 'Soft, tight-crumbed white loaf in the Agege style. Slices cleanly for sandwiches and toasts well.', 2200, '/products/agege-loaf.svg', array['/products/agege-loaf.svg', '/products/agege-loaf-detail.svg']::text[], 'breads', 40, 'Bestseller'),
  ('bdfd408e-af5c-5d5c-a9e6-a5b3f22b8ea5', 'Coconut Bread', 'coconut-bread', 'A lightly sweet round loaf with toasted coconut in the dough and on the crust.', 2800, '/products/coconut-bread.svg', array['/products/coconut-bread.svg', '/products/coconut-bread-detail.svg']::text[], 'breads', 18, null),
  ('2d9d617f-1cbe-534e-8032-f83caa75e435', 'Sweet Potato & Millet Loaf', 'sweet-potato-millet-loaf', 'A slow-fermented tin loaf with roasted sweet potato and millet. Moist, nutty and good for a week.', 4500, '/products/sweet-potato-millet-loaf.svg', array['/products/sweet-potato-millet-loaf.svg', '/products/sweet-potato-millet-loaf-detail.svg']::text[], 'breads', 12, 'New'),
  ('39fdcb07-d720-5a17-bf85-8f98b8ab0e47', 'Honey Whole-Wheat Loaf', 'honey-wheat-loaf', 'A dense, soft whole-wheat sandwich loaf sweetened with honey instead of refined sugar.', 3400, '/products/honey-wheat-loaf.svg', array['/products/honey-wheat-loaf.svg', '/products/honey-wheat-loaf-detail.svg']::text[], 'breads', 4, null),
  ('ac57f397-838c-541c-aa5f-45b3b10be637', 'Beef Meat Pie, Box of 6', 'meat-pie-box', 'Flaky butter pastry filled with spiced beef, potato and carrot. Best warmed for ten minutes.', 5400, '/products/meat-pie-box.svg', array['/products/meat-pie-box.svg', '/products/meat-pie-box-detail.svg']::text[], 'pastries', 25, 'Bestseller'),
  ('cae70d36-49a8-5932-8e42-b9a25a99a9bb', 'Puff Puff, Box of 20', 'puff-puff-box', 'Golden, airy fried dough balls with a hint of nutmeg. Made on the day you collect them.', 3000, '/products/puff-puff-box.svg', array['/products/puff-puff-box.svg', '/products/puff-puff-box-detail.svg']::text[], 'pastries', 30, 'Bestseller'),
  ('0d3a0f93-4b90-55f8-9083-70017e64b601', 'Chin Chin Jar, 500 g', 'chin-chin-jar', 'Crunchy, lightly spiced fried pastry cubes in a reusable glass jar. Keeps for weeks.', 4200, '/products/chin-chin-jar.svg', array['/products/chin-chin-jar.svg', '/products/chin-chin-jar-detail.svg']::text[], 'pastries', 22, null),
  ('2d317757-5821-5cd3-9c8d-bde389c3d134', 'Hibiscus Cinnamon Rolls, Box of 4', 'hibiscus-cinnamon-rolls', 'Soft rolls swirled with cinnamon and a tart hibiscus filling, finished with a light glaze.', 4800, '/products/hibiscus-cinnamon-rolls.svg', array['/products/hibiscus-cinnamon-rolls.svg', '/products/hibiscus-cinnamon-rolls-detail.svg']::text[], 'pastries', 14, 'New'),
  ('0704e5d3-8052-5edc-9ed5-1feaa8747388', 'Spiced Banana Bread', 'spiced-banana-bread', 'Ripe banana, ginger and cinnamon in a moist loaf with a crisp, caramelised top.', 3500, '/products/spiced-banana-bread.svg', array['/products/spiced-banana-bread.svg', '/products/spiced-banana-bread-detail.svg']::text[], 'cakes', 16, null),
  ('a9d3e179-35ec-5a3d-b30e-cf6cfd8bb6d0', 'Ginger Pound Cake', 'ginger-pound-cake', 'A buttery pound cake with fresh and ground ginger. Dense, sunny and excellent with tea.', 6500, '/products/ginger-pound-cake.svg', array['/products/ginger-pound-cake.svg', '/products/ginger-pound-cake-detail.svg']::text[], 'cakes', 9, null),
  ('850d6690-25c3-5a99-add2-81229b92fae9', 'Hibiscus Layer Cake', 'hibiscus-layer-cake', 'Two vanilla sponge layers, cream cheese frosting and a deep red hibiscus drip. Serves 10 to 12.', 14000, '/products/hibiscus-layer-cake.svg', array['/products/hibiscus-layer-cake.svg', '/products/hibiscus-layer-cake-detail.svg']::text[], 'cakes', 5, 'New'),
  ('09a9de59-aa86-50c3-9214-169691394056', 'Coconut & Lime Cake', 'coconut-lime-cake', 'Coconut sponge brushed with lime syrup and covered in lime cream. Serves 10 to 12.', 12500, '/products/coconut-lime-cake.svg', array['/products/coconut-lime-cake.svg', '/products/coconut-lime-cake-detail.svg']::text[], 'cakes', 0, null),
  ('0a949ce0-7c97-5fad-be9b-b2b5731cc826', 'Suya Spice (Yaji), 150 g', 'suya-spice-yaji', 'Roasted peanut, ginger, paprika and chilli blended for suya, grilled chicken and roasted plantain.', 2500, '/products/suya-spice-yaji.svg', array['/products/suya-spice-yaji.svg', '/products/suya-spice-yaji-detail.svg']::text[], 'spices', 60, 'Bestseller'),
  ('2a24a3dc-883f-5c9c-89c3-ff9e4ff33fdf', 'Jollof Spice Blend, 120 g', 'jollof-spice-blend', 'Thyme, curry, bay, garlic and dried pepper in the ratio we use for party jollof.', 2400, '/products/jollof-spice-blend.svg', array['/products/jollof-spice-blend.svg', '/products/jollof-spice-blend-detail.svg']::text[], 'spices', 45, null),
  ('452b0103-1352-5bef-8939-5dce1a22d283', 'Zobo Spice Mix, 100 g', 'zobo-spice-mix', 'Ginger, cloves and dried pineapple peel for brewing zobo, or for spiced bakes.', 2200, '/products/zobo-spice-mix.svg', array['/products/zobo-spice-mix.svg', '/products/zobo-spice-mix-detail.svg']::text[], 'spices', 38, null),
  ('8e7a4937-284c-5957-8ecc-cec7ce9e26f9', 'Spice Discovery Box', 'spice-discovery-box', 'Small jars of yaji, jollof blend and zobo mix in a gift box. A good place to start.', 8900, '/products/spice-discovery-box.svg', array['/products/spice-discovery-box.svg', '/products/spice-discovery-box-detail.svg']::text[], 'spices', 20, 'New')
